tokens := 5.0 // 桶里当前有多少令牌
rate := 2.0 // 每秒补充多少个令牌
burst := 5.0 // 桶容量，也就是突发上限
last := time.Now()
now := time.Now()
tokens += now.Sub(last).Seconds() * rate // 按流逝的时间补充令牌
if tokens > burst {
	tokens = burst
}
if tokens >= 1 {
	tokens--
	fmt.Println("放行")
} else {
	fmt.Println("限流")
}
